import json
snap = json.load(open('meta/0007_snapshot.json'))
for tname, t in snap['tables'].items():
    for fname, fk in t.get('foreignKeys', {}).items():
        print(tname, 'FK', fname, fk.get('columnsFrom'), '->', fk.get('tableTo'), fk.get('columnsTo'))
    for uname, uc in t.get('uniqueConstraints', {}).items():
        print(tname, 'UNIQUE', uname, uc.get('columns'))
"

